<?php
/**
 * Antalya POS Extra Add-on Delete Handler
 *
 * @package Antalya_POS
 * @since 6.4
 */

if (!defined('ABSPATH')) {
    exit;
}

if (isset($_GET['del_extra'])) {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have sufficient permissions to perform this action.', 'antalya-pos'));
    }

    $extra_id = intval($_GET['del_extra']);
    if ($extra_id > 0) {
        // Verify CSRF nonce generated by wp_nonce_url() in extra-list.php & extra-view.php
        check_admin_referer('rtpos_delete_extra_' . $extra_id);

        global $wpdb;
        $t_extras  = $wpdb->prefix . 'rtpos_extras';
        $svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

        $deleted = $wpdb->delete(
            $t_extras,
            ['id' => $extra_id],
            ['%d']
        );

        if ($deleted !== false) {
            echo '<div class="apos-alert ex-alert-flex">' . $svg_check . '<span>' . sprintf(
                /* translators: %d: extra add-on ID */
                esc_html__('Extra #%d deleted successfully!', 'antalya-pos'),
                $extra_id
            ) . '</span></div>';
        }
    }
}